insert into public.tournament_sites (slug,name,catalog_name,operator_family,base_url,promo_index_url,winners_url,rules_url,event_tz,sweeps_unit,units_per_usd,playthrough_x,min_redeem_sweeps,excluded_states,public_pages,status,cadence_days,graduated_at,notes) values ('luckparty', 'Luck Party', 'Luck Party', 'blazesoft', 'https://luckparty.com', 'https://luckparty.com/promotions', 'https://luckparty.com/promotions/promo/latest-winners-victory-vault-luck-party', 'https://luckparty.com/sweeps-rules', 'America/New_York', 'SC', 1, 1, 50, array['IN']::text[], true, 'dedicated', 1, now(), 'Graduated on day one (2026-10-02): five-event weekly rotation since at least May 2026, all ending 12:59 PM ET (11:59 AM CT): Max Multiplier (Mon-Tue), Max Spins (Tue-Thu), Hit the Multiplier (Thu-Fri), Max Total Play (Fri-Mon), Weekly Spin Raffle (Mon-Mon). Promo pages and the Victory Vault winners page are public; leaderboards, min bets and paytables need a login. An ended event''s URL redirects to the promotions hub (title ''No Deposit Casino Bonuses and Promotions Hub''), so read live pages while they are live. Victory Vault had not been updated past Jul 6 as of 2026-10-02. Sweeps Rules v1.3 (2026-09-01): 100 SC = $100, 1x playthrough, 50 SC min redeem, 9,550 SC/day max, 10,000 SC win cap per 48h, odds may be changed by the operator. excluded_states is partial: Indiana exit July 2026; read the full list from rules_url.')
